import { createSlice, createAsyncThunk, createSelector } from "@reduxjs/toolkit";
import axios from "axios";

// Django backend URL
const API_URL = "http://127.0.0.1:8000/api/users/";

// --- Thunks (API calls) ---

// Fetch all users
export const fetchUsersAsync = createAsyncThunk("users/fetchAll", async () => {
  const token = localStorage.getItem("token");
  const res = await axios.get(API_URL, {
    headers: { Authorization: `Bearer ${token}` },
  });
  return res.data.map(user => ({
    ...user,
    profile: user.profile || { bio: "", phone: "" },
  }));
});

// Update user
export const updateUserAsync = createAsyncThunk("users/update", async (user) => {
  const token = localStorage.getItem("token");
  const res = await axios.put(`${API_URL}${user.id}/`, user, {
    headers: { Authorization: `Bearer ${token}` },
  });
  return { ...res.data, profile: res.data.profile || { bio: "", phone: "" } };
});

// Delete user
export const deleteUserAsync = createAsyncThunk("users/delete", async (id) => {
  const token = localStorage.getItem("token");
  await axios.delete(`${API_URL}${id}/`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  return id;
});

// --- State ---
const initialState = {
  users: [],
  searchTerm: "",
  viewUserData: null,
  isEditMode: false,
  loading: false,
  error: null,
};

// --- Slice ---
const usersSlice = createSlice({
  name: "users",
  initialState,
  reducers: {
    setSearchTerm(state, action) {
      state.searchTerm = action.payload;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchUsersAsync.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchUsersAsync.fulfilled, (state, action) => {
        state.loading = false;
        state.users = action.payload;
      })
      .addCase(fetchUsersAsync.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message || "Failed to fetch users";
      })
      .addCase(updateUserAsync.fulfilled, (state, action) => {
        const updated = action.payload;
        const i = state.users.findIndex((u) => u.id === updated.id);
        if (i !== -1) state.users[i] = updated;
      })
      .addCase(deleteUserAsync.fulfilled, (state, action) => {
        state.users = state.users.filter((u) => u.id !== action.payload);
      });
  },
});

// Selectors
export const selectUsersState = (state) => state.users;
export const selectFilteredUsers = createSelector(
  [selectUsersState],
  (s) =>
    s.users.filter((u) =>
      (u.username || "").toLowerCase().includes((s.searchTerm || "").toLowerCase())
    )
);

export default usersSlice.reducer;
